mapper.select:
SELECT id FROM async_task WHERE BINARY task_key=BINARY #{taskKey}
  AND BINARY owner_module=BINARY #{ownerModule} AND BINARY task_type=BINARY #{taskType}
  AND BINARY biz_type=BINARY #{bizType} AND biz_id=#{bizId}
  AND expected_version <=> #{expectedVersion} AND payload_json=CAST(#{payloadJson} AS JSON)
  AND max_retry_count=#{maxRetryCount} AND BINARY retry_policy=BINARY #{retryPolicy}
FOR UPDATE

mapper.update:
UPDATE async_task SET status='RUNNING',lease_owner=#{owner},
lease_until=TIMESTAMPADD(MICROSECOND,#{micros},NOW(3)), version=#{version}, updated_at=NOW(3)
WHERE id=#{taskId}
